export const SCHEMA_SCHEMAS_PRIVACY_DATA_ASSET_SCHEMA_JSON = "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://ai-sdlc.org/schemas/privacy/data-asset.schema.json\",\n  \"title\": \"Personal Data Asset & PII Inventory Schema (DATA-ASSET-*)\",\n  \"type\": \"object\",\n  \"required\": [\n    \"id\",\n    \"type\",\n    \"title\",\n    \"status\",\n    \"version\",\n    \"classification\",\n    \"pii-categories\",\n    \"data-subjects\",\n    \"retention-period\",\n    \"erasure-method\"\n  ],\n  \"properties\": {\n    \"id\": {\n      \"type\": \"string\",\n      \"pattern\": \"^DATA-ASSET-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n    },\n    \"type\": {\n      \"type\": \"string\",\n      \"const\": \"data-asset\"\n    },\n    \"version\": {\n      \"type\": \"string\",\n      \"pattern\": \"^[0-9]+\\\\.[0-9]+\\\\.[0-9]+(-[0-9A-Za-z.-]+)?$\",\n      \"description\": \"Data asset semantic version (SemVer).\"\n    },\n    \"schema-version\": {\n      \"type\": \"string\"\n    },\n    \"title\": {\n      \"type\": \"string\",\n      \"minLength\": 3\n    },\n    \"status\": {\n      \"type\": \"string\",\n      \"enum\": [\n        \"draft\",\n        \"active\",\n        \"deprecated\",\n        \"retired\"\n      ]\n    },\n    \"classification\": {\n      \"type\": \"string\",\n      \"enum\": [\n        \"public\",\n        \"internal\",\n        \"confidential-pii\",\n        \"special-category-sensitive\"\n      ],\n      \"description\": \"Data sensitivity classification aligned with privacy-policy.yaml.\"\n    },\n    \"pii-categories\": {\n      \"type\": \"array\",\n      \"minItems\": 1,\n      \"items\": {\n        \"type\": \"string\",\n        \"enum\": [\n          \"identifiers\",\n          \"contact\",\n          \"authentication\",\n          \"financial\",\n          \"location\",\n          \"behavioral\",\n          \"biometric\",\n          \"health\",\n          \"telemetry-operator\"\n        ]\n      }\n    },\n    \"data-subjects\": {\n      \"type\": \"array\",\n      \"minItems\": 1,\n      \"items\": {\n        \"type\": \"string\",\n        \"pattern\": \"^ACT-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n      },\n      \"description\": \"Product actors (ACT-*) whose personal data is stored or processed.\"\n    },\n    \"fields\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"name\",\n          \"sensitivity\",\n          \"masking-strategy\"\n        ],\n        \"properties\": {\n          \"name\": {\n            \"type\": \"string\",\n            \"minLength\": 1\n          },\n          \"sensitivity\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"public\",\n              \"internal\",\n              \"pii\",\n              \"special-category\"\n            ]\n          },\n          \"masking-strategy\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"none\",\n              \"redact\",\n              \"sha256-salt\",\n              \"tokenize\",\n              \"aes-256-gcm\",\n              \"truncate\"\n            ]\n          }\n        },\n        \"additionalProperties\": false\n      }\n    },\n    \"retention-period\": {\n      \"type\": \"string\",\n      \"pattern\": \"^([0-9]+(d|m|y)|session-only|indefinite-anonymized)$\",\n      \"description\": \"Maximum retention TTL (e.g. 30d, 12m, 5y, session-only, indefinite-anonymized).\"\n    },\n    \"erasure-method\": {\n      \"type\": \"string\",\n      \"enum\": [\n        \"hard-delete\",\n        \"crypto-shredding\",\n        \"irreversible-anonymization\"\n      ]\n    },\n    \"owner-bounded-context\": {\n      \"type\": \"string\",\n      \"pattern\": \"^(BC|CMP)-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n    },\n    \"supersedes\": {\n      \"type\": [\n        \"string\",\n        \"null\"\n      ],\n      \"pattern\": \"^DATA-ASSET-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n    },\n    \"superseded-by\": {\n      \"type\": [\n        \"string\",\n        \"null\"\n      ],\n      \"pattern\": \"^DATA-ASSET-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n    }\n  },\n  \"additionalProperties\": false\n}";

export const SCHEMA_SCHEMAS_PRIVACY_PRIVACY_POLICY_SCHEMA_JSON = "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://ai-sdlc.org/schemas/privacy/privacy-policy.schema.json\",\n  \"title\": \"Privacy-by-Design as Code Governance Policy Schema\",\n  \"type\": \"object\",\n  \"required\": [\n    \"version\",\n    \"project\",\n    \"regulatory_frameworks\",\n    \"default_action\",\n    \"classifications\",\n    \"agent_guardrails\",\n    \"ci_gates\"\n  ],\n  \"properties\": {\n    \"id\": {\n      \"type\": \"string\",\n      \"pattern\": \"^(PRIV-POL|POL-PRIV)-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n    },\n    \"type\": {\n      \"type\": \"string\",\n      \"const\": \"privacy-policy\"\n    },\n    \"version\": {\n      \"type\": \"string\",\n      \"minLength\": 1\n    },\n    \"project\": {\n      \"type\": \"string\",\n      \"minLength\": 1\n    },\n    \"regulatory_frameworks\": {\n      \"type\": \"array\",\n      \"minItems\": 1,\n      \"items\": {\n        \"type\": \"string\",\n        \"enum\": [\n          \"GDPR\",\n          \"LOPDGDD\",\n          \"ISO-27701\",\n          \"CCPA\",\n          \"HIPAA\",\n          \"LGPD\"\n        ]\n      }\n    },\n    \"default_action\": {\n      \"type\": \"string\",\n      \"enum\": [\n        \"DENY_UNREGISTERED_PII\",\n        \"ALLOW\",\n        \"REVIEW_REQUIRED\"\n      ]\n    },\n    \"classifications\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"public\",\n        \"internal\",\n        \"confidential_pii\",\n        \"special_category_sensitive\"\n      ],\n      \"additionalProperties\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"action\",\n          \"encryption_at_rest\",\n          \"encryption_in_transit\",\n          \"allow_in_logs\",\n          \"allow_in_ai_prompts\"\n        ],\n        \"properties\": {\n          \"action\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"ALLOW\",\n              \"STRICT_GOVERNANCE\",\n              \"DPIA_APPROVAL_REQUIRED\",\n              \"DENY\"\n            ]\n          },\n          \"description\": {\n            \"type\": \"string\"\n          },\n          \"exception_requires\": {\n            \"type\": \"string\"\n          },\n          \"require_ropa_entry\": {\n            \"type\": \"boolean\"\n          },\n          \"require_dpia_artifact\": {\n            \"type\": \"boolean\"\n          },\n          \"encryption_at_rest\": {\n            \"type\": \"boolean\"\n          },\n          \"encryption_in_transit\": {\n            \"type\": \"boolean\"\n          },\n          \"require_field_level_encryption\": {\n            \"type\": \"boolean\"\n          },\n          \"allow_in_logs\": {\n            \"type\": \"boolean\"\n          },\n          \"log_masking_strategy\": {\n            \"type\": \"string\"\n          },\n          \"allow_in_ai_prompts\": {\n            \"type\": \"boolean\"\n          },\n          \"max_retention_days\": {\n            \"type\": \"integer\",\n            \"minimum\": 1\n          },\n          \"require_right_to_erasure\": {\n            \"type\": \"boolean\"\n          }\n        },\n        \"additionalProperties\": false\n      }\n    },\n    \"cross_border_transfers\": {\n      \"type\": \"object\",\n      \"properties\": {\n        \"allowed_regions\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"string\"\n          }\n        },\n        \"require_scc_for_third_countries\": {\n          \"type\": \"boolean\"\n        },\n        \"approved_subprocessors\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"string\"\n          }\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"agent_guardrails\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"forbid_real_pii_in_tests\",\n        \"forbid_pii_in_console_or_logger\",\n        \"require_dto_projection_for_pii\"\n      ],\n      \"properties\": {\n        \"forbid_real_pii_in_tests\": {\n          \"type\": \"boolean\"\n        },\n        \"forbid_pii_in_console_or_logger\": {\n          \"type\": \"boolean\"\n        },\n        \"require_dto_projection_for_pii\": {\n          \"type\": \"boolean\"\n        },\n        \"on_special_category_detected\": {\n          \"type\": \"object\",\n          \"required\": [\n            \"action\",\n            \"notification_tag\",\n            \"message\"\n          ],\n          \"properties\": {\n            \"action\": {\n              \"type\": \"string\"\n            },\n            \"notification_tag\": {\n              \"type\": \"string\"\n            },\n            \"message\": {\n              \"type\": \"string\"\n            }\n          },\n          \"additionalProperties\": false\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"ci_gates\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"fail_on_unregistered_pii\",\n        \"fail_on_pii_in_logs\",\n        \"fail_on_missing_retention_policy\",\n        \"generate_ropa_inventory\",\n        \"output_ropa_file\",\n        \"output_privacy_report\"\n      ],\n      \"properties\": {\n        \"fail_on_unregistered_pii\": {\n          \"type\": \"boolean\"\n        },\n        \"fail_on_pii_in_logs\": {\n          \"type\": \"boolean\"\n        },\n        \"fail_on_missing_retention_policy\": {\n          \"type\": \"boolean\"\n        },\n        \"fail_on_unapproved_subprocessor\": {\n          \"type\": \"boolean\"\n        },\n        \"generate_ropa_inventory\": {\n          \"type\": \"boolean\"\n        },\n        \"output_ropa_file\": {\n          \"type\": \"string\"\n        },\n        \"output_privacy_report\": {\n          \"type\": \"string\"\n        }\n      },\n      \"additionalProperties\": false\n    }\n  },\n  \"additionalProperties\": false\n}";

