export const SCHEMA_SCHEMAS_SECURITY_ENCLAVE_SCHEMA_JSON = "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://ai-sdlc.org/schemas/security/enclave.schema.json\",\n  \"title\": \"Security Enclave Schema (Zero Trust Architecture Boundary)\",\n  \"type\": \"object\",\n  \"required\": [\n    \"id\",\n    \"type\",\n    \"title\",\n    \"status\",\n    \"version\",\n    \"trust-zone\",\n    \"perimeter-rules\",\n    \"allowed-inbound\",\n    \"allowed-outbound\"\n  ],\n  \"properties\": {\n    \"id\": {\n      \"type\": \"string\",\n      \"pattern\": \"^SEC-ENC-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n    },\n    \"type\": {\n      \"type\": \"string\",\n      \"const\": \"security-enclave\"\n    },\n    \"version\": {\n      \"type\": \"string\",\n      \"pattern\": \"^[0-9]+\\\\.[0-9]+\\\\.[0-9]+(-[0-9A-Za-z.-]+)?$\",\n      \"description\": \"Security enclave semantic version (SemVer).\"\n    },\n    \"schema-version\": {\n      \"type\": \"string\"\n    },\n    \"title\": {\n      \"type\": \"string\",\n      \"minLength\": 3\n    },\n    \"status\": {\n      \"type\": \"string\",\n      \"enum\": [\n        \"draft\",\n        \"active\",\n        \"deprecated\",\n        \"retired\"\n      ]\n    },\n    \"trust-zone\": {\n      \"type\": \"string\",\n      \"enum\": [\n        \"untrusted\",\n        \"semi-trusted\",\n        \"trusted\",\n        \"highly-trusted\",\n        \"dmz\",\n        \"zero-trust-boundary\"\n      ],\n      \"description\": \"Zero Trust confidence zone assigned to enclave.\"\n    },\n    \"trust-level\": {\n      \"type\": \"string\",\n      \"description\": \"Descriptive Zero Trust confidence level.\"\n    },\n    \"isolation\": {\n      \"type\": \"string\",\n      \"description\": \"Technical perimeter isolation mechanism.\"\n    },\n    \"perimeter-rules\": {\n      \"type\": \"array\",\n      \"minItems\": 1,\n      \"items\": {\n        \"type\": \"string\"\n      },\n      \"description\": \"Perimeter rules defining enclave security boundary (e.g. mTLS, IP allowlist).\"\n    },\n    \"allowed-inbound\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"string\",\n        \"pattern\": \"^(CMP|SEC-ENC)-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n      },\n      \"description\": \"Components or enclaves authorized to initiate inbound connections.\"\n    },\n    \"allowed-outbound\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"string\",\n        \"pattern\": \"^(CMP|SEC-ENC)-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n      },\n      \"description\": \"Components or enclaves this enclave can connect to.\"\n    },\n    \"enforced-by\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"string\",\n        \"pattern\": \"^SEC-REQ-[A-Z0-9]+(-[A-Z0-9]+)*$\"\n      },\n      \"description\": \"Security requirements enforcing this enclave's rules.\"\n    },\n    \"authentication-mechanism\": {\n      \"type\": \"string\",\n      \"enum\": [\n        \"mtls\",\n        \"jwt\",\n        \"api-key\",\n        \"oauth2\",\n        \"none\"\n      ],\n      \"description\": \"Authentication mechanism required at enclave perimeter.\"\n    },\n    \"supersedes\": {\n      \"type\": [\n        \"string\",\n        \"null\"\n      ]\n    },\n    \"superseded-by\": {\n      \"type\": [\n        \"string\",\n        \"null\"\n      ]\n    }\n  },\n  \"additionalProperties\": false\n}";

